code_example:
// Print literal string
printf("Hello, C.\n");

// Print integer value
int count = 5;
printf("Count is %d\n", count);

// Print double (formatted)
double price = 19.99;
printf("Price: $%.2f\n", price);

// Print address (pointer)
int* ptr = &count;
printf("Address: %p\n", (void*)ptr);

// Print string variable
const char* msg = "Done.";
printf("%s\n", msg);

// String output (automatically adds newline)
puts("Quick message.");

// Single character output
putchar('!');
